    depth = 1
    while bottom - top - 2*depth > 3 and right - left - 2*depth > 3:
        color = 2 if depth % 2 else 5
        r1, r2 = top + depth, bottom - depth
        c1, c2 = left + depth, right - depth
        if depth == 1:
